acked_at=IF(?,NOW(),packed_at) WHERE id=?')->execute([$complete?'PACKED':'PACKING',current_user()['id'],$complete?1:0,$id]);db()->commit();$msg='PACK OK · '.$a['sku'].' · '.$a['product_name'];if($complete){publish_event('ONLINE_PACK_COMPLETE','Order packed',online_order_number($id).' · ready for dispatch',['super_admin'],'online_order',$id,null);publish_scoped_event('ONLINE_PACK_COMPLETE','Order packed',online_order_number($id).' · ready for dispatch',['manager','godown'],'online_order',$id);}}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=$e->getMessage();}}
